contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // the deployer (this contract) holds TIMELOCK_ADMIN_ROLE and can grant PROPOSER_ROLE to itself
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        require(!c.isOperation(c.hashOperation(target, value, data, predecessor, salt)), "id already used");
        if (delay < 1) {
            delay = 1;
        }
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        c.schedule(target, value, data, predecessor, salt, delay);
        assert(c.isOperation(id) && c.isOperationPending(id) && c.getTimestamp(id) > block.timestamp);
        c.cancel(id);
        assert(!c.isOperation(id) && c.getTimestamp(id) == 0 && !c.isOperationPending(id));
    }

    receive() external payable {}
}

