contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 salt, uint256 delay, uint256 minDelay) public payable {
        require(minDelay > 0, "minDelay must be positive");
        require(delay < minDelay, "delay must be too small");
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        bool reverted;
        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), salt);
        // top-level state-changing calls are not inside try/catch, so wrap via a
        // separate top-level call pattern: attempt schedule and detect revert
        // by checking state afterwards instead of try/catch nesting.
        // Perform the call; if it reverts, catch here at top level.
        try this.doSchedule(address(this), 0, "", bytes32(0), salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && !c.isOperation(id));
    }

    function doSchedule(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) external {
        c.schedule(target, value, data, predecessor, salt, delay);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 role, address account) public {
        require(account != address(0), "zero account");
        require(!c.hasRole(role, account), "account must not already have role");

        bool beforeGrant = c.hasRole(role, account);

        c.grantRole(role, account);
        bool afterGrant = c.hasRole(role, account);

        c.revokeRole(role, account);
        bool afterRevoke = c.hasRole(role, account);

        assert(!beforeGrant && afterGrant && !afterRevoke);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 id) public payable {
        require(!c.isOperation(id));
        bool pending = c.isOperationPending(id);
        bool ready = c.isOperationReady(id);
        bool done = c.isOperationDone(id);
        uint256 ts = c.getTimestamp(id);
        bool reverted;
        try c.cancel(id) { reverted = false; } catch { reverted = true; }
        assert(reverted && !pending && !ready && !done && ts == 0 && !c.isOperation(id));
    }
    receive() external payable {}
}

