contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value, bytes calldata data, bytes32 salt, uint256 delay) public {
        // make this contract a proposer so schedule can be attempted
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        uint256 minDelay = c.getMinDelay();
        bytes32 id = c.hashOperation(target, value, data, bytes32(0), salt);
        bool reverted;
        if (delay >= minDelay) {
            c.schedule(target, value, data, bytes32(0), salt, delay);
            reverted = false;
        } else {
            try c.schedule(target, value, data, bytes32(0), salt, delay) { reverted = false; }
            catch { reverted = true; }
        }
        assert((delay < minDelay) ? (reverted && !c.isOperation(id)) : (!reverted && c.isOperationPending(id)));
    }
    receive() external payable {}
}

